@contextmanager
def reraise(errors, into):
    """Reraises errors by passing them into the into callback."""
    errors = _ensure_exceptable(errors)
    try:
        yield
    except errors as e:
        raise into(e)


@decorator
def reraise_dec(errors, into):
    """Decorator version of reraise - passes original exception into callback."""
    errors = _ensure_exceptable(errors)
    try:
        return call()
    except errors as e:
        raise into(e)

